import React, { useState } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const QuanLyHoaDon = () => {
    const now = new Date();
    const currentMonth = now.getMonth() + 1;
    const currentYear = now.getFullYear();

    const [selectedMonth, setSelectedMonth] = useState(currentMonth);
    const [selectedYear, setSelectedYear] = useState(currentYear);

    const years = [2024, 2025, 2026];
    const months = Array.from({ length: 12 }, (_, i) => i + 1);

    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    const isCurrentOrFuture = selectedYear > currentYear || (selectedYear === currentYear && selectedMonth >= currentMonth);
    const totalReceived = isCurrentOrFuture ? 0 : (5000000 * 45);

    return (
        <div style={{
            height: '100vh', // Ép chiều cao cố định bằng màn hình để không bị cuộn trang web
            display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden', padding: '20px'
        }}>

            {/* Header */}
            <div style={{ padding: '10px 20px', color: '#fff', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <h2 style={{ margin: 0, textShadow: '1px 1px 4px rgba(0,0,0,0.5)' }}>Quản lý hoá đơn</h2>
                <div style={{ display: 'flex', gap: '10px' }}>
                    <select 
                        value={selectedMonth} 
                        onChange={(e) => setSelectedMonth(parseInt(e.target.value))}
                        style={{ padding: '8px', borderRadius: '10px', border: 'none', fontWeight: 'bold', cursor: 'pointer' }}
                    >
                        {months.map(m => <option key={m} value={m}>Tháng {m}</option>)}
                    </select>
                    <select 
                        value={selectedYear} 
                        onChange={(e) => setSelectedYear(parseInt(e.target.value))}
                        style={{ padding: '8px', borderRadius: '10px', border: 'none', fontWeight: 'bold', cursor: 'pointer' }}
                    >
                        {years.map(y => <option key={y} value={y}>Năm {y}</option>)}
                    </select>
                </div>
            </div>

            <div style={{ flex: 1, display: 'flex', gap: '30px', overflow: 'hidden', marginTop: '10px' }}>

                {/* CỘT TRÁI: DANH SÁCH PHÒNG (Cuộn độc lập) */}
                <div style={{ 
                    width: '220px', display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', 
                    gap: '8px', alignContent: 'flex-start', overflowY: 'auto',
                    padding: '15px', backgroundColor: 'rgba(255,255,255,0.15)',
                    borderRadius: '25px', border: '1px solid rgba(255,255,255,0.2)',
                    maxHeight: '100%' 
                }}>
                    {allRooms.map(room => {
                        const isPaid = !isCurrentOrFuture;
                        return (
                            <div key={room} style={{ 
                                background: isPaid ? 'white' : '#ffcc00', 
                                color: '#333', padding: '10px 0', borderRadius: '10px', 
                                textAlign: 'center', fontSize: '12px', fontWeight: 'bold',
                                border: '1px solid rgba(0,0,0,0.05)', cursor: 'default', userSelect: 'none'
                            }}>
                                {room}
                            </div>
                        );
                    })}
                </div>

                {/* CỘT PHẢI: KHUNG TRẮNG (Cố định, chỉ cuộn nội dung bên trong) */}
                <div style={{ 
                    flex: 1, backgroundColor: '#ffffff', borderRadius: '30px', 
                    padding: '30px', display: 'flex', flexDirection: 'column',
                    color: '#333', boxShadow: '0 10px 40px rgba(0,0,0,0.2)',
                    overflow: 'hidden' // Ngăn khung trắng bị kéo dài ra
                }}>
                    {/* Tổng tiền - Cố định ở trên */}
                    <div style={{ 
                        marginBottom: '20px', padding: '20px', backgroundColor: '#f9f9f9', 
                        borderRadius: '20px', borderLeft: '6px solid #8b5e5e'
                    }}>
                        <div style={{ fontSize: '15px', fontWeight: '600', color: '#777' }}>Tổng tiền đã nhận {selectedMonth}/{selectedYear}:</div>
                        <div style={{ color: totalReceived > 0 ? '#2ecc71' : '#bdc3c7', fontSize: '32px', fontWeight: '800' }}>
                            {totalReceived.toLocaleString()}đ
                        </div>
                    </div>

                    <h3 style={{ borderBottom: '2px solid #f0f0f0', paddingBottom: '12px', margin: '0 0 10px 0' }}>Lịch sử giao dịch</h3>

                    {/* KHUNG CUỘN LỊCH SỬ (Giống khung chat) */}
                    <div style={{ 
                        flex: 1, 
                        overflowY: 'auto', // Chỉ cuộn phần này
                        paddingRight: '10px'
                    }}>
                        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                            <thead style={{ position: 'sticky', top: 0, backgroundColor: '#fff', zIndex: 10 }}>
                                <tr style={{ textAlign: 'left', color: '#aaa', fontSize: '13px', textTransform: 'uppercase' }}>
                                    <th style={{ padding: '12px 10px', borderBottom: '2px solid #eee' }}>Phòng</th>
                                    <th style={{ padding: '12px 10px', borderBottom: '2px solid #eee' }}>Số tiền</th>
                                    <th style={{ padding: '12px 10px', borderBottom: '2px solid #eee' }}>Nội dung</th>
                                    <th style={{ padding: '12px 10px', borderBottom: '2px solid #eee' }}>Thời gian</th>
                                </tr>
                            </thead>
                            <tbody>
                                {!isCurrentOrFuture ? (
                                    allRooms.map(room => (
                                        <tr key={room} style={{ borderBottom: '1px solid #f5f5f5' }}>
                                            <td style={{ padding: '15px 10px', fontWeight: '700' }}>{room}</td>
                                            <td style={{ padding: '15px 10px', color: '#27ae60', fontWeight: '600' }}>5.000.000đ</td>
                                            <td style={{ padding: '15px 10px', fontSize: '14px', color: '#555' }}>
                                                Chuyển khoản tiền phòng tháng {selectedMonth} - {selectedYear}
                                            </td>
                                            <td style={{ padding: '15px 10px', fontSize: '12px', color: '#999' }}>
                                                01/{selectedMonth.toString().padStart(2, '0')}/{selectedYear} 09:15
                                            </td>
                                        </tr>
                                    ))
                                ) : (
                                    <tr>
                                        <td colSpan="4" style={{ textAlign: 'center', padding: '100px 0', color: '#ccc', fontStyle: 'italic' }}>
                                            Chưa có dữ liệu thanh toán...
                                        </td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default QuanLyHoaDon;
